CREATE TABLE attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),case_id uuid NOT NULL REFERENCES intake_cases(id),location_id uuid NOT NULL REFERENCES provider_locations(id),storage_key uuid NOT NULL UNIQUE,display_name text NOT NULL,media_type text NOT NULL CHECK(media_type IN ('application/pdf','image/jpeg','image/png','text/plain')),size_bytes integer NOT NULL CHECK(size_bytes>0 AND size_bytes<=5242880),uploaded_by text NOT NULL,scan_state text NOT NULL DEFAULT 'not_configured' CHECK(scan_state IN ('not_configured','pending','clean','rejected')),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX attachments_case_idx ON attachments(case_id,created_at);
